(()=>{'use strict';const token=location.hash.slice(1),form=document.getElementById('partner-public-form'),status=document.getElementById('partner-public-status');history.replaceState(null,'',location.pathname);if(!/^[a-f0-9]{64}$/.test(token)){form.hidden=true;status.textContent='Open the private registration link supplied by CAGE.';return;}form.onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const details=Object.fromEntries(new FormData(form));details.consent=form.elements.consent.checked;const c=window.CAGE_CONFIG;if(!c?.supabaseUrl||!c?.supabaseAnonKey)throw Error('Registration is unavailable. Please contact CAGE.');const r=await fetch(c.supabaseUrl+'/rest/v1/rpc/hub_partner_submit',{method:'POST',headers:{'Content-Type':'application/json',apikey:c.supabaseAnonKey,Authorization:'Bearer '+c.supabaseAnonKey},body:JSON.stringify({token_value:token,details})});if(!r.ok){const body=await r.json().catch(()=>({}));throw Error(body.message||'Could not submit. Please contact CAGE.');}form.hidden=true;status.textContent='Thank you. Your details have been received for staff verification. You do not need to submit again.';}catch(err){status.textContent=err.message;}finally{b.disabled=false;}};})();
